public class FastDateFormat_format_TriageGen2Test {

    @Test
    public void testFormatWithTimeZoneForcedTrue() {
        // Setup: Create a FastDateFormat instance where mTimeZoneForced is true.
        // Since the constructor is protected, we use getInstance(pattern, timeZone) 
        // which internally sets the timezone and triggers the override logic.
        String pattern = "yyyy-MM-dd HH:mm:ss";
        TimeZone tz = TimeZone.getTimeZone("UTC");
        FastDateFormat fdf = FastDateFormat.getInstance(pattern, tz);

        // Force the internal state via getInstance logic (FastDateFormat handles timezone overrides)
        // In FastDateFormat, if a TimeZone is provided to getInstance, it uses it.

        Calendar calendar = Calendar.getInstance(TimeZone.getTimeZone("GMT+8"));
        calendar.set(2023, Calendar.OCTOBER, 27, 10, 0, 0);
        calendar.set(Calendar.MILLISECOND, 0);

        StringBuffer buf = new StringBuffer();

        // When mTimeZoneForced is true, it should use the internal mTimeZone (UTC) 
        // instead of the calendar's timezone (GMT+8).
        // 10:00 GMT+8 is 02:00 UTC.
        StringBuffer result = fdf.format(calendar, buf);

        assertEquals("2023-10-27 02:00:00", result.toString());
        // Verify buffer was actually appended to
        assertTrue(buf.length() > 0);
    }

    @Test
    public void testFormatWithTimeZoneForcedFalse() {
        // Setup: Create a FastDateFormat instance using the default (no specific timezone provided)
        // This typically results in mTimeZoneForced being false.
        String pattern = "yyyy-MM-dd";
        FastDateFormat fdf = FastDateFormat.getInstance(pattern);

        Calendar calendar = Calendar.getInstance();
        calendar.set(2023, Calendar.JANUARY, 1);

        StringBuffer buf = new StringBuffer();
        StringBuffer result = fdf.format(calendar, buf);

        // Should respect the calendar's timezone
        assertEquals("2023-01-01", result.toString());
    }

    @Test
    public void testFormatWithDifferentLocale() {
        String pattern = "EEEE"; // Day name
        Locale locale = Locale.FRENCH;
        FastDateFormat fdf = FastDateFormat.getInstance(pattern, locale);

        Calendar calendar = Calendar.getInstance();
        calendar.set(2023, Calendar.MONDAY, 1); // Jan 1 2023 was Sunday, let's use a known Monday
        calendar.set(2023, Calendar.JANUARY, 2); 

        StringBuffer buf = new StringBuffer();
        StringBuffer result = fdf.format(calendar, buf);

        // Monday in French is "lundi"
        assertEquals("lundi", result.toString().toLowerCase());
    }

    @Test
    public void testFormatReuseBuffer() {
        String pattern = "HH:mm";
        FastDateFormat fdf = FastDateFormat.getInstance(pattern);

        Calendar calendar = Calendar.getInstance();
        calendar.set(2023, 0, 1, 12, 30);

        StringBuffer buf = new StringBuffer("Prefix: ");
        StringBuffer result = fdf.format(calendar, buf);

        // Check if it appended to the existing buffer
        assertTrue(result.toString().startsWith("Prefix: "));
        assertTrue(result.toString().contains("12:30"));
    }

    @Test
    public void testFormatWithDateTimeInstance() {
        // Test using the getDateInstance/getTimeInstance factory methods
        FastDateFormat fdf = FastDateFormat.getDateTimeInstance(Calendar.SHORT, Calendar.SHORT);
        Calendar calendar = Calendar.getInstance();
        calendar.set(2023, Calendar.MAY, 20, 15, 45);

        StringBuffer buf = new StringBuffer();
        StringBuffer result = fdf.format(calendar, buf);

        assertNotNull(result);
        assertFalse(result.length() == 0);
    }
}
